import { test } from 'node:test';
import assert from 'node:assert/strict';
import { formatarListaDeCompras } from './solution.mjs';

test('junta os itens com vírgula e espaço por padrão', () => {
  assert.equal(formatarListaDeCompras(['arroz', 'feijão', 'café']), 'arroz, feijão, café');
});

test('aceita um separador personalizado', () => {
  assert.equal(formatarListaDeCompras(['a', 'b', 'c'], '-'), 'a-b-c');
  assert.equal(formatarListaDeCompras(['Ana', 'Beto'], ' e '), 'Ana e Beto');
});

test('lista vazia vira texto vazio', () => {
  assert.equal(formatarListaDeCompras([]), '');
});

test('recusa valor que não é lista', () => {
  assert.throws(() => formatarListaDeCompras('arroz,feijão'));
});

solutionCode:
export function formatarListaDeCompras(lista, separador = ', ') {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.join(separador);
}
